static int sysmon_prepare ( struct rproc_subdev * subdev ) { struct qcom_sysmon * sysmon = container_of ( subdev , qcom_sysmon , subdev ) ; struct sysmon_event event = { . subsys_name = sysmon -> name . ssr_event = SSCTL_SSR_EVENT_BEFORE_POWERUP } ; mutex_lock ( & sysmon -> state_lock ) ; sysmon -> state = SSCTL_SSR_EVENT_BEFORE_POWERUP ; mutex_unlock ( & sysmon -> state_lock ) ; return 0 ; } 